import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.HashMap;
import java.util.Map;

/**
 * Service for processing user profiles.
 */
public class UserProfileService {

    private static final Logger logger = LoggerFactory.getLogger(UserProfileService.class);

    private final Map<String, UserProfile> userDatabase;

    public UserProfileService() {
        this.userDatabase = new HashMap<>();
        initializeUserData();
    }

    /**
     * Initialize pre-existing user data in the system.
     */
    private void initializeUserData() {
        userDatabase.put("1", new UserProfile("1", "John Doe", "330101199001011234", "13800138000"));
        userDatabase.put("2", new UserProfile("2", "Jane Smith", "330101199202025678", "13912345678"));
    }

    /**
     * Process user profile by userId.
     *
     * @param userId the user ID to process
     */
    public void processUserProfile(String userId) {
        try {
            if (userId == null || userId.trim().isEmpty()) {
                logger.warn("Invalid userId provided: null or empty");
                return;
            }

            UserProfile userProfile = fetchUserProfile(userId);

            if (userProfile != null) {
                logger.info("Processing user profile for userId: {}, username: {}", 
                        userProfile.getUserId(), userProfile.getUsername());
            } else {
                logger.info("No user profile found for userId: {}", userId);
            }

        } catch (Exception e) {
            logger.error("Error processing user profile for userId: {}", userId, e);
        }
    }

    /**
     * Fetch user profile from the simulated database.
     *
     * @param userId the user ID to fetch
     * @return UserProfile if found, null otherwise
     */
    private UserProfile fetchUserProfile(String userId) {
        return userDatabase.get(userId);
    }
}

